-- Public transplant-games meet catalogue seeded from transplant_games_events.json.
create table if not exists public.meet_catalog (
  id uuid primary key default gen_random_uuid(),
  catalog_key text not null unique,
  category text not null check (category in ('World Transplant Games', 'National Transplant Games')),
  category_order smallint not null check (category_order between 1 and 2),
  series_id text not null,
  series_name text not null,
  name text not null,
  year smallint not null,
  edition_number smallint,
  host_city text,
  host_country text,
  meet_date date,
  end_date date,
  status text not null check (status in ('completed', 'in_progress', 'upcoming', 'cancelled', 'date_unconfirmed')),
  source_url text,
  source_metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_date is null or meet_date is null or end_date >= meet_date)
);

create index if not exists meet_catalog_picker_idx
  on public.meet_catalog (category_order, year desc, name);
create index if not exists meet_catalog_date_idx on public.meet_catalog (meet_date desc nulls last);

alter table public.meet_catalog enable row level security;
drop policy if exists "Meet catalogue is public" on public.meet_catalog;
create policy "Meet catalogue is public" on public.meet_catalog
  for select to anon, authenticated using (true);
grant select on public.meet_catalog to anon, authenticated;

