on conflict (catalog_key) do update set
  category = excluded.category, category_order = excluded.category_order, series_id = excluded.series_id,
  series_name = excluded.series_name, name = excluded.name, year = excluded.year, edition_number = excluded.edition_number,
  host_city = excluded.host_city, host_country = excluded.host_country, meet_date = excluded.meet_date,
  end_date = excluded.end_date, status = excluded.status, source_url = excluded.source_url,
  source_metadata = excluded.source_metadata, updated_at = now();

alter table public.submitted_meets
  add column if not exists catalog_meet_id uuid references public.meet_catalog(id) on delete set null;

drop index if exists public.submitted_meets_identity_idx;
create unique index if not exists submitted_meets_catalog_identity_idx
  on public.submitted_meets (catalog_meet_id, course, coalesce(opening_ceremony_date, meet_date))
  where catalog_meet_id is not null;
create unique index if not exists submitted_meets_custom_identity_idx
  on public.submitted_meets (lower(name), meet_date, lower(location), course, is_world_transplant_games, coalesce(opening_ceremony_date, meet_date))
  where catalog_meet_id is null;

create index if not exists submitted_meets_catalog_meet_idx on public.submitted_meets (catalog_meet_id);
